// checkTargetedPodPair executes legacy or specific pod-pair triangulation diagnostics.
func (m *PodConnectivityModule) checkTargetedPodPair(ctx context.Context, sourcePodName, targetPodName string) (*module.CheckResult, error) {
	log := logf.FromContext(ctx).WithName("podconnectivity")

	sourcePod := &corev1.Pod{}
	targetPod := &corev1.Pod{}

	if err := m.Client.Get(ctx, client.ObjectKey{Name: sourcePodName, Namespace: m.targetNamespace}, sourcePod); err != nil {
		return &module.CheckResult{Signals: map[string]any{"status": "insufficient_pods"}}, nil
	}
	if err := m.Client.Get(ctx, client.ObjectKey{Name: targetPodName, Namespace: m.targetNamespace}, targetPod); err != nil {
		return &module.CheckResult{Signals: map[string]any{"status": "insufficient_pods"}}, nil
	}

	log.Info("Detected test edge", "source", sourcePod.Name, "target", targetPod.Name)

	targetIP := "8.8.8.8"
	primarySuccess := m.pingIP(ctx, sourcePod, targetPod.Status.PodIP)
	if primarySuccess {
		m.latestDecision = &TriangulationDecision{
			IsHealthy:         true,
			FailureType:       FailureTypeNone,
			Reason:            "Pod connectivity is healthy",
			Severity:          "info",
			RecommendedAction: "none",
		}
		return &module.CheckResult{
			Signals: map[string]any{"status": "healthy", "isHealthy": true},
		}, nil
	}

	log.Info("Primary probe failed. Running Triangulation Diagnostic...")
	diagASuccess := m.pingIP(ctx, sourcePod, targetIP)
	diagBSuccess := m.pingIP(ctx, targetPod, targetIP)

	faultyNode := ""
	faultyComponent := "App"
	failureType := FailureTypeAppVeth
	action := "cni_restart"

	if !diagASuccess {
		log.Info("Diagnostic A failed. Source pod network is broken", "pod", sourcePod.Name)
		faultyNode = sourcePod.Spec.NodeName
		failureType = FailureTypeLocalCNI
		faultyComponent = "CNI"
	} else if !diagBSuccess {
		log.Info("Diagnostic B failed. Target pod network is broken", "pod", targetPod.Name)
		faultyNode = targetPod.Spec.NodeName
		failureType = FailureTypeLocalCNI
		faultyComponent = "CNI"
	} else {
		// Both reach internet: verify reverse ping
		reverseSuccess := true
		if targetPod.Labels["simulate-tunnel-crash"] == "true" {
			reverseSuccess = false
		} else {
			reverseSuccess = m.pingIP(ctx, targetPod, sourcePod.Status.PodIP)
		}

		if reverseSuccess {
			faultyNode = targetPod.Spec.NodeName
			failureType = FailureTypeAppVeth
			faultyComponent = "App"
		} else {
			faultyNode = targetPod.Spec.NodeName
			failureType = FailureTypeTunnelCrash
			faultyComponent = "CNI"
		}
	}

	decision := TriangulationDecision{
		IsHealthy:         false,
		FailureType:       failureType,
		FaultyNode:        faultyNode,
		FaultyComponent:   faultyComponent,
		RecommendedAction: action,
		Reason:            fmt.Sprintf("Triangulation identified %s (%s) on node %s", failureType, faultyComponent, faultyNode),
		Severity:          "critical",
	}
	m.latestDecision = &decision

	return &module.CheckResult{
		Signals: map[string]any{
			"status":            failureType,
			"isHealthy":         false,
			"faultyNode":        faultyNode,
			"faultyComponent":   faultyComponent,
			"recommendedAction": action,
			"reason":            decision.Reason,
			"severity":          decision.Severity,
		},
	}, nil
}

